import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * figma: Message Scroller — the transcript viewport, with the scroll behaviour
 * a chat actually needs.
 *
 *   <MessageScrollerProvider autoScroll scrollPreviousItemPeek={48} initialPosition="last-anchor">
 *     <MessageScrollerViewport>
 *       <MessageScrollerItem messageId="m1" scrollAnchor>…</MessageScrollerItem>
 *       <MessageScrollerItem messageId="m2">…</MessageScrollerItem>
 *     </MessageScrollerViewport>
 *   </MessageScrollerProvider>
 *
 * Concepts, from the kit's recipes:
 *   - A **turn** starts a new exchange; the row that begins it carries
 *     `scrollAnchor`. In a group chat the anchor is the message that asks for a
 *     reply, or a marker like "Marcus joined" — not every user message.
 *   - `scrollPreviousItemPeek` keeps a slice of the previous item visible above
 *     the anchor so the reader keeps context.
 *   - `autoScroll` follows streamed replies only while the reader is at the
 *     live edge; scrolling away releases the view.
 *   - Prepending older rows preserves the visible row rather than jumping.
 *   - `initialPosition="last-anchor"` opens a saved thread at the last turn
 *     rather than the absolute end.
 *
 * Hooks: useMessageScroller (imperative control),
 * useMessageScrollerVisibility (which anchor is in view),
 * useMessageScrollerScrollable (which edges can still scroll).
 */
type ScrollerContextValue = {
  viewportRef: React.RefObject<HTMLDivElement | null>;
  registerItem: (id: string, node: HTMLElement | null, isAnchor: boolean) => void;
  scrollToMessage: (id: string, opts?: { behavior?: ScrollBehavior }) => void;
  scrollToLatest: (opts?: { behavior?: ScrollBehavior }) => void;
  anchors: string[];
  activeAnchor: string | null;
  atLiveEdge: boolean;
  canScrollUp: boolean;
  canScrollDown: boolean;
  scrollPreviousItemPeek: number;
};

const ScrollerContext = React.createContext<ScrollerContextValue | null>(null);

function useScroller() {
  const ctx = React.useContext(ScrollerContext);
  if (!ctx) throw new Error("MessageScroller parts must be used within <MessageScrollerProvider>.");
  return ctx;
}

/** Imperative control — jump to a message, or back to the live edge. */
function useMessageScroller() {
  const { scrollToMessage, scrollToLatest, anchors } = useScroller();
  return { scrollToMessage, scrollToLatest, anchors };
}

/** Which anchored turn the reader is currently looking at. */
function useMessageScrollerVisibility() {
  const { activeAnchor, anchors } = useScroller();
  return { activeAnchor, anchors };
}

/** Scroll state — which edges the viewport can still scroll toward. */
function useMessageScrollerScrollable() {
  const { canScrollUp, canScrollDown, atLiveEdge } = useScroller();
  return { canScrollUp, canScrollDown, atLiveEdge };
}

function MessageScrollerProvider({
  children,
  autoScroll = false,
  scrollPreviousItemPeek = 0,
  initialPosition = "last-anchor",
}: {
  children: React.ReactNode;
  autoScroll?: boolean;
  /** Pixels of the previous item to keep visible above the anchor. */
  scrollPreviousItemPeek?: number;
  initialPosition?: "last-anchor" | "end" | "start";
}) {
  const viewportRef = React.useRef<HTMLDivElement | null>(null);
  const itemsRef = React.useRef(new Map<string, { node: HTMLElement; isAnchor: boolean }>());
  const orderRef = React.useRef<string[]>([]);
  const [anchors, setAnchors] = React.useState<string[]>([]);
  const [activeAnchor, setActiveAnchor] = React.useState<string | null>(null);
  const [atLiveEdge, setAtLiveEdge] = React.useState(true);
  const [canScrollUp, setCanScrollUp] = React.useState(false);
  const [canScrollDown, setCanScrollDown] = React.useState(false);
  const didInit = React.useRef(false);

  const registerItem = React.useCallback(
    (id: string, node: HTMLElement | null, isAnchor: boolean) => {
      if (!node) {
        itemsRef.current.delete(id);
        orderRef.current = orderRef.current.filter((x) => x !== id);
      } else {
        itemsRef.current.set(id, { node, isAnchor });
        if (!orderRef.current.includes(id)) orderRef.current.push(id);
      }
      setAnchors(orderRef.current.filter((x) => itemsRef.current.get(x)?.isAnchor));
    },
    []
  );

  const scrollToMessage = React.useCallback(
    (id: string, opts?: { behavior?: ScrollBehavior }) => {
      const viewport = viewportRef.current;
      const entry = itemsRef.current.get(id);
      if (!viewport || !entry) return;
      const top = entry.node.offsetTop - viewport.offsetTop - scrollPreviousItemPeek;
      viewport.scrollTo({ top: Math.max(0, top), behavior: opts?.behavior ?? "smooth" });
    },
    [scrollPreviousItemPeek]
  );

  const scrollToLatest = React.useCallback((opts?: { behavior?: ScrollBehavior }) => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    viewport.scrollTo({ top: viewport.scrollHeight, behavior: opts?.behavior ?? "smooth" });
  }, []);

  // Track scroll position: live edge, scrollable edges, and the anchor in view.
  React.useEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    const onScroll = () => {
      const distanceFromBottom =
        viewport.scrollHeight - viewport.scrollTop - viewport.clientHeight;
      setAtLiveEdge(distanceFromBottom < 24);
      setCanScrollUp(viewport.scrollTop > 0);
      setCanScrollDown(distanceFromBottom > 1);

      let current: string | null = null;
      for (const id of orderRef.current) {
        const entry = itemsRef.current.get(id);
        if (!entry?.isAnchor) continue;
        if (entry.node.offsetTop - viewport.offsetTop <= viewport.scrollTop + 1) current = id;
      }
      setActiveAnchor(current);
    };
    onScroll();
    viewport.addEventListener("scroll", onScroll, { passive: true });
    return () => viewport.removeEventListener("scroll", onScroll);
  }, []);

  // Open at the last anchor rather than the absolute end.
  React.useEffect(() => {
    if (didInit.current || !viewportRef.current) return;
    if (!orderRef.current.length) return;
    didInit.current = true;
    if (initialPosition === "start") return;
    if (initialPosition === "end") {
      scrollToLatest({ behavior: "auto" });
      return;
    }
    const last = orderRef.current.filter((x) => itemsRef.current.get(x)?.isAnchor).pop();
    if (last) scrollToMessage(last, { behavior: "auto" });
    else scrollToLatest({ behavior: "auto" });
  }, [initialPosition, scrollToLatest, scrollToMessage, anchors.length]);

  // Follow streamed content only while the reader is at the live edge, and
  // preserve the visible row when older messages are prepended above.
  React.useEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    let previousHeight = viewport.scrollHeight;
    const observer = new MutationObserver(() => {
      const grewBy = viewport.scrollHeight - previousHeight;
      if (grewBy === 0) return;
      const grewAbove =
        viewport.scrollTop > 0 && viewport.scrollHeight - viewport.scrollTop > previousHeight;
      if (grewAbove && !atLiveEdge) viewport.scrollTop += grewBy;
      else if (autoScroll && atLiveEdge) viewport.scrollTop = viewport.scrollHeight;
      previousHeight = viewport.scrollHeight;
    });
    observer.observe(viewport, { childList: true, subtree: true, characterData: true });
    return () => observer.disconnect();
  }, [autoScroll, atLiveEdge]);

  return (
    <ScrollerContext.Provider
      value={{
        viewportRef, registerItem, scrollToMessage, scrollToLatest,
        anchors, activeAnchor, atLiveEdge, canScrollUp, canScrollDown, scrollPreviousItemPeek,
      }}
    >
      {children}
    </ScrollerContext.Provider>
  );
}

function MessageScrollerViewport({ className, ...props }: React.ComponentProps<"div">) {
  const { viewportRef } = useScroller();
  return (
    <div
      ref={viewportRef}
      data-slot="message-scroller-viewport"
      className={cn("relative flex flex-1 flex-col gap-4 overflow-y-auto overscroll-contain p-4", className)}
      {...props}
    />
  );
}

/**
 * One row. `scrollAnchor` marks it as the start of a turn — the row the
 * viewport scrolls to. Keep `messageId` and `scrollAnchor` on the element even
 * when you wrap it in a motion component.
 */
function MessageScrollerItem({
  className,
  messageId,
  scrollAnchor = false,
  ...props
}: React.ComponentProps<"div"> & { messageId: string; scrollAnchor?: boolean }) {
  const { registerItem } = useScroller();
  const ref = React.useCallback(
    (node: HTMLDivElement | null) => registerItem(messageId, node, scrollAnchor),
    [messageId, scrollAnchor, registerItem]
  );
  return (
    <div
      ref={ref}
      data-slot="message-scroller-item"
      data-message-id={messageId}
      data-scroll-anchor={scrollAnchor || undefined}
      className={cn("scroll-mt-4", className)}
      {...props}
    />
  );
}

/**
 * The scroll frame. Convenience root that pairs the provider with the
 * viewport for the common case.
 *
 * When controls live *outside* the frame — a search result list, a permalink,
 * a "jump to latest" button — use MessageScrollerProvider and
 * MessageScrollerViewport separately so those controls sit inside the provider
 * and can call the hooks.
 */
function MessageScroller({
  autoScroll,
  scrollPreviousItemPeek,
  initialPosition,
  ...props
}: React.ComponentProps<typeof MessageScrollerViewport> &
  Omit<React.ComponentProps<typeof MessageScrollerProvider>, "children">) {
  return (
    <MessageScrollerProvider
      autoScroll={autoScroll}
      scrollPreviousItemPeek={scrollPreviousItemPeek}
      initialPosition={initialPosition}
    >
      <MessageScrollerViewport {...props} />
    </MessageScrollerProvider>
  );
}

export {
  MessageScroller,
  MessageScrollerProvider,
  MessageScrollerViewport,
  MessageScrollerItem,
  useMessageScroller,
  useMessageScrollerVisibility,
  useMessageScrollerScrollable,
};
